describe('fmt.chunk', () => {
  it('groups the digits into the sizes the design asked for', () => {
    expect(fmt('784198512345671', [['chunk', '3-4-7-1']])).toBe('784-1985-1234567-1');
  });
  it('strips NON-DIGITS first, so an already-formatted value re-chunks', () => {
    // this is the case that was broken: the strip matched a literal "D", so a
    // value carrying separators never reached the right length
    expect(fmt('784-1985-1234567-1', [['chunk', '3-4-7-1']])).toBe('784-1985-1234567-1');
  });
  it('returns the input untouched when the digits do not fit the sizes', () => {
    expect(fmt('12345', [['chunk', '3-4-7-1']])).toBe('12345');
    expect(fmt('12345', [['chunk', '']])).toBe('12345');
  });
});

describe('fmt.eidyear', () => {
  it('reads the birth year out of a 15-digit Emirates ID', () => {
    expect(fmt('784198512345671', [['eidyear']])).toBe('1985');
  });
  it('reads it through the separators the card is printed with', () => {
    expect(fmt('784-1985-1234567-1', [['eidyear']])).toBe('1985');
  });
  it('answers BLANK rather than guessing', () => {
    // an invented birth year on an identity document is worse than a gap
    expect(fmt('123198512345671', [['eidyear']])).toBe(''); // not a 784 card
    expect(fmt('7841985', [['eidyear']])).toBe(''); // too short
    expect(fmt('784180012345671', [['eidyear']])).toBe(''); // year before 1900
    expect(fmt('784999912345671', [['eidyear']])).toBe(''); // year in the future
  });
});

describe('fmt.daysago', () => {
  it('turns a number of days into the date that many days back', () => {
    const want = new Date(Date.now() - 7 * 86400000).toISOString().slice(0, 10);
    expect(fmt('7', [['daysago']])).toBe(want);
    expect(fmt('0', [['daysago']])).toBe(new Date().toISOString().slice(0, 10));
  });
  it('reads a chip left untouched through the fallback before it', () => {
    const want = new Date(Date.now() - 30 * 86400000).toISOString().slice(0, 10);
    expect(fmt('', [['fallback', '30'], ['daysago']])).toBe(want);
  });
  it('answers BLANK for anything that is not a number', () => {
    expect(fmt('', [['daysago']])).toBe('');
    expect(fmt('week', [['daysago']])).toBe('');
  });
});

