describe('ruleNav', () => {
  const nav = () => {
    const seen: Array<[string, string, unknown]> = [];
    return {
      seen,
      navigation: { reset: (s: unknown) => seen.push(['reset', '', s]) },
      go: (_n: unknown, method: 'navigate' | 'replace', target: string, params?: never) =>
        seen.push([method, target, params]),
    };
  };
  it('does nothing when the rule names no target', () => {
    const n = nav();
    ruleNav({ navigateTo: '' } as never, n.navigation, { method: 'navigate', goTo: n.go });
    expect(n.seen).toEqual([]);
  });
  it('RESETS instead of pushing when the rule carries resetTo', () => {
    const n = nav();
    ruleNav({ navigateTo: 'Home', resetTo: '' } as never, n.navigation, { method: 'navigate', goTo: n.go });
    expect(n.seen[0]?.[0]).toBe('reset');
  });
  it('pushes through the screen-supplied go when it does not', () => {
    const n = nav();
    ruleNav({ navigateTo: 'Home' } as never, n.navigation, { method: 'replace', goTo: n.go });
    expect(n.seen).toEqual([['replace', 'Home', undefined]]);
  });
  it('RESOLVES a flow outcome to a real screen before going there', async () => {
    const n = nav();
    ruleNav({ navigateTo: 'AfterLogin' } as never, n.navigation, {
      method: 'navigate',
      goTo: n.go,
      flows: ['AfterLogin'],
      resolveFlow: async (intended) => intended + 'Resolved',
    });
    await new Promise((r) => setTimeout(r, 0));
    expect(n.seen).toEqual([['navigate', 'AfterLoginResolved', undefined]]);
  });
});

