describe('the repeat-row helpers', () => {
  it('seeds one implicit row when the section is empty', () => {
    expect(rowsOf({}, 'k')).toEqual([{ id: 'r0' }]);
    expect(rowsOf({ k: [] }, 'k')).toEqual([{ id: 'r0' }]);
    expect(rowsOf({ k: 'not an array' }, 'k')).toEqual([{ id: 'r0' }]);
  });
  it('reads a row id as a string, a NUMBER, or the map index', () => {
    expect(ridOf({ id: 'r7' })).toBe('r7');
    expect(ridOf({ id: 3 })).toBe('3');
    expect(ridOf({}, 2)).toBe('2');
    expect(ridOf({})).toBe('');
    // an OBJECT id would have stringified to "[object Object]" and collided
    expect(ridOf({ id: { nested: true } }, 5)).toBe('5');
  });
  it('appends a row, and honours the design cap', () => {
    const w: Array<[string, unknown]> = [];
    addRow({}, (k, v) => w.push([k, v]), 'k');
    expect((w[0]?.[1] as unknown[]).length).toBe(2);
    w.length = 0;
    addRow({ k: [{ id: 'a' }, { id: 'b' }] }, (k, v) => w.push([k, v]), 'k', 2);
    expect(w).toEqual([]); // at the cap, nothing written
  });
  it('removes BY ID, and never the last row', () => {
    const w: Array<[string, unknown]> = [];
    removeRow({ k: [{ id: 'a' }, { id: 'b' }] }, (k, v) => w.push([k, v]), 'k', 'a');
    expect(w[0]?.[1]).toEqual([{ id: 'b' }]);
    w.length = 0;
    // the section would vanish — the bug that made every row but the first
    // deletable, then none
    removeRow({ k: [{ id: 'a' }] }, (k, v) => w.push([k, v]), 'k', 'a');
    expect(w).toEqual([]);
  });
});

/**
 * The SDK failure envelope.
 *
 * Every wired integration press goes through safeInvoke and then shows
 * responseMessage(data). The arms below are the ones that decide whether the
 * user sees an actionable sentence or engine-speak — "Cannot convert null value
 * to object" is what Hermes says when a missing native module is called, and it
 * must never reach a screen.
 */
describe('safeInvoke', () => {
  it('turns a SYNCHRONOUS throw into a settled failure', async () => {
    const boom = new Error('sync boom');
    await expect(safeInvoke(() => { throw boom; })).resolves.toEqual({ ok: false, data: boom });
  });
  it('turns a REJECTION into a settled failure', async () => {
    const boom = new Error('async boom');
    await expect(safeInvoke(async () => { throw boom; })).resolves.toEqual({ ok: false, data: boom });
  });
  it('reports a missing native module by name when told one', async () => {
    await expect(safeInvoke(() => undefined, 'react-native-thing')).resolves.toEqual({
      ok: false,
      data: { missingNativeModule: 'react-native-thing' },
    });
  });
  it('reports a bare failure when it was not', async () => {
    await expect(safeInvoke(() => null)).resolves.toEqual({ ok: false });
  });
  it('passes a real result straight through', async () => {
    await expect(safeInvoke(async () => ({ ok: true, data: 1 }))).resolves.toEqual({ ok: true, data: 1 });
  });
});

