/**
 * The PIN keypad's display, in the two shapes a design draws it as.
 *
 * The UNDERLINE variant is the one nothing reached: its geometry is computed
 * from boxWidth when the design gave no explicit width, and the filled slot
 * takes the accent colour. The busy flag is the guard that stops a keystroke
 * passcode is being sealed — the difference between one save and several.
 */
/**
 * The device-capability probes, in the answers a real handset gives.
 *
 * Every one of these is a flow GATE: a wrong answer sends the user down the
 * wrong branch. The rule the module is built on is that not-knowing is its own
 * answer — 'unknown' is never silently promoted to yes, and biometryKind
 * returns null rather than naming a modality it had to guess.
 */
/**
 * Flow conditions that decide on RESPONSE DATA rather than on the device.
 *
 * Driven through resolveFlow, not by reaching into the helpers, because the
 * thing worth protecting is the whole path: a seeded response body, a step
 * that reads it, and the branch the user actually lands on.
 *
 * The age check is the one that matters most. It is a GATE — the wrong answer
 * lets an underage customer through, or blocks an eligible one — and the
 * Emirates ID is not a fallback in practice but the path that runs, since dob
 * is null on every observed customer record.
 */
describe('flow conditions that read a response body', () => {
  const BID = 'binding:self';
  const flow = (data: Record<string, unknown>) => ({
    start: 'q',
    steps: {
      q: { check: null, data: { bindingId: BID, ...data }, label: 'Eligible?', yes: 'Yes', no: 'No' },
    },
    self: 'Here',
  });
  afterEach(() => clearResponses());

  it('reads a DOB and answers the age gate from it', async () => {
    const old = new Date();
    old.setFullYear(old.getFullYear() - 30);
    setLastResponse(BID, { customer: { dob: old.toISOString().slice(0, 10) } });
    await expect(
      resolveFlow(flow({ kind: 'age', dobPath: 'customer.dob', minimum: 18 }) as never, 'Here'),
    ).resolves.toBe('Yes');
  });
  it('refuses an underage DOB', async () => {
    const young = new Date();
    young.setFullYear(young.getFullYear() - 10);
    setLastResponse(BID, { customer: { dob: young.toISOString().slice(0, 10) } });
    await expect(
      resolveFlow(flow({ kind: 'age', dobPath: 'customer.dob', minimum: 18 }) as never, 'Here'),
    ).resolves.toBe('No');
  });
  it('falls back to the EMIRATES ID when dob is null, which is the real path', async () => {
    setLastResponse(BID, { customer: { dob: null, idn: '784199012345678' } });
    await expect(
      resolveFlow(
        flow({ kind: 'age', dobPath: 'customer.dob', idnPath: 'customer.idn', minimum: 18 }) as never,
        'Here',
      ),
    ).resolves.toBe('Yes');
  });
  it('reads a FORMATTED Emirates ID — the separators are stripped, not the letter D', async () => {
    // guards the two-pass backslash: a /D/g strip leaves the dashes in, the
    // length test then fails, and the gate silently falls through to a guess
    setLastResponse(BID, { customer: { dob: null, idn: '784-1990-1234567-8' } });
    await expect(
      resolveFlow(
        flow({ kind: 'age', dobPath: 'customer.dob', idnPath: 'customer.idn', minimum: 18 }) as never,
        'Here',
      ),
    ).resolves.toBe('Yes');
  });
  it('rejects an Emirates ID that is the wrong length or the wrong prefix', async () => {
    for (const idn of ['78419901234567', '123199012345678', '']) {
      clearResponses();
      setLastResponse(BID, { customer: { dob: null, idn } });
      // unanswerable → the guess keeps the designed destination reachable
      await expect(
        resolveFlow(
          flow({ kind: 'age', dobPath: 'customer.dob', idnPath: 'customer.idn' }) as never,
          'Here',
        ),
      ).resolves.toBe('Yes');
    }
  });
  it('never stringifies an OBJECT into the date or the digit strip', async () => {
    setLastResponse(BID, { customer: { dob: { nested: true }, idn: { nested: true } } });
    await expect(
      resolveFlow(
        flow({ kind: 'age', dobPath: 'customer.dob', idnPath: 'customer.idn' }) as never,
        'Here',
      ),
    ).resolves.toBe('Yes');
  });

  it('answers every comparison operator against the response field', async () => {
    const cases: Array<[string, unknown, unknown, string]> = [
      ['eq', 'a', 'a', 'Yes'],
      ['ne', 'a', 'b', 'Yes'],
      ['lt', 1, 2, 'Yes'],
      ['lte', 2, 2, 'Yes'],
      ['gt', 3, 2, 'Yes'],
      ['gte', 2, 2, 'Yes'],
      ['in', 'b', ['a', 'b'], 'Yes'],
      ['in', 'z', ['a', 'b'], 'No'],
      ['matches', 'abc', '^a', 'Yes'],
      ['matches', 'xbc', '^a', 'No'],
      ['exists', 'v', undefined, 'Yes'],
    ];
    for (const [op, actual, want, expected] of cases) {
      clearResponses();
      setLastResponse(BID, { f: actual });
      await expect(
        resolveFlow(flow({ kind: 'responseField', path: 'f', op, value: want }) as never, 'Here'),
      ).resolves.toBe(expected);
    }
  });
  it('says NOTHING rather than false when the response has not arrived', async () => {
    // no seeded body at all — the step cannot answer, so the guess stands and
    // the designed destination is still reachable
    await expect(
      resolveFlow(flow({ kind: 'responseField', path: 'f', op: 'eq', value: 1 }) as never, 'Here'),
    ).resolves.toBe('Yes');
  });
  it('walks a dot path, and gives up on a path that leaves the object', async () => {
    setLastResponse(BID, { a: { b: { c: 7 } } });
    await expect(
      resolveFlow(flow({ kind: 'responseField', path: 'a.b.c', op: 'eq', value: 7 }) as never, 'Here'),
    ).resolves.toBe('Yes');
    clearResponses();
    setLastResponse(BID, { a: 1 });
    await expect(
      resolveFlow(flow({ kind: 'responseField', path: 'a.b.c', op: 'exists' }) as never, 'Here'),
    ).resolves.toBe('No');
  });
});

