describe('CodeInput', () => {
  const draw = (el: React.ReactElement): { json: unknown; writes: string[] } => {
    let tree!: renderer.ReactTestRenderer;
    act(() => { tree = renderer.create(el); });
    const writes: string[] = [];
    for (const node of tree.root.findAll(() => true, { deep: true })) {
      const fn = (node.props as Record<string, unknown>).onChangeText;
      if (typeof fn === 'function') {
        act(() => (fn as (t: string) => void)('12'));
        writes.push('12');
      }
    }
    const json = tree.toJSON();
    act(() => tree.unmount());
    return { json, writes };
  };
  it('draws the BOX variant with the design border', () => {
    const { json } = draw(
      <CodeInput length={4} boxWidth={40} boxHeight={48} boxRadius={8} gap={8}
        boxColor="#fff" boxBorderColor="#000" boxBorderWidth={2}
        dotColor="#000" textColor="#000" fontSize={16} onComplete={() => undefined} />,
    );
    expect(json).toBeTruthy();
  });
  it('draws a borderless box when the design gave no border colour', () => {
    const { json } = draw(
      <CodeInput length={4} boxWidth={40} boxHeight={48} boxRadius={8} gap={8}
        boxColor="#fff" dotColor="#000" textColor="#000" fontSize={16}
        onComplete={() => undefined} />,
    );
    expect(json).toBeTruthy();
  });
  it('draws the UNDERLINE variant, sizing it from boxWidth when unspecified', () => {
    const { json } = draw(
      <CodeInput length={4} boxWidth={40} boxHeight={48} boxRadius={0} gap={8}
        dotColor="#000" textColor="#000" fontSize={16}
        underlineColor="#ccc" underlineAccentColor="#f00" value="1"
        onComplete={() => undefined} />,
    );
    expect(json).toBeTruthy();
  });
  it('honours explicit underline geometry when the design measured it', () => {
    const { json } = draw(
      <CodeInput length={4} boxWidth={40} boxHeight={48} boxRadius={0} gap={8}
        dotColor="#000" textColor="#000" fontSize={16}
        underlineColor="#ccc" underlineWidth={24} underlineHeight={3} underlineInset={4}
        onComplete={() => undefined} />,
    );
    expect(json).toBeTruthy();
  });
  it('SWALLOWS a keystroke while busy, so one save cannot become several', () => {
    const seen: string[] = [];
    const { json } = draw(
      <CodeInput length={4} boxWidth={40} boxHeight={48} boxRadius={8} gap={8}
        boxColor="#fff" dotColor="#000" textColor="#000" fontSize={16} busy
        onComplete={(v) => seen.push(v)} />,
    );
    expect(json).toBeTruthy();
    expect(seen).toEqual([]);
  });
});

describe('the state-tint helpers', () => {
  it('carries a colour only while the state holds', () => {
    expect(tintWhen(true, '#f00')).toEqual({ color: '#f00' });
    expect(tintWhen(false, '#f00')).toEqual({});
    expect(colorWhen(true, '#f00')).toBe('#f00');
    expect(colorWhen(false, '#f00')).toBeUndefined();
  });
  it('dims a control that is present but not usable', () => {
    expect(opacityWhen(true, 0.5)).toBe(1);
    expect(opacityWhen(false, 0.5)).toBe(0.5);
  });
  it('removes a press handler while the control is gated', () => {
    const h = () => undefined;
    expect(pressWhen(true, h)).toBe(h);
    expect(pressWhen(false, h)).toBeUndefined();
    expect(pressUnless(false, h)).toBe(h);
    expect(pressUnless(true, h)).toBeUndefined();
  });
});
